  "schema_version": "rs-shopping-audit/3",
  "checks": {
    "naturalness": "pass",
    "extraction_fidelity": "fail",
    "fact_boundary": "pass",
    "clarification_policy": "pass"
  },
  "reasons": {
    "naturalness": "顾客的问题自然且明确，是询问安装前如何核对型号和尺寸的技术咨询。",
    "extraction_fidelity": "主要意图、回答目标和背景顾虑提取基本忠实；但把改装用途记为 strict 商品要求，容易将咨询背景误作可评分的硬条件。所列引用均为原文连续逐字片段。",
    "fact_boundary": "提取结果没有把目录商品或历史记录冒充为顾客当前设备，也没有据历史推断其设备型号或偏好。将其标为 self 有顾客关于自己手头设备及改装计划的文本依据；画像不相关的处理恰当。",
    "clarification_policy": "顾客询问核对方法，可以先说明检查项目，不必先索取显卡和冷排型号；未知型号只会限制对具体兼容性的判断，并不妨碍回答方法。"
  },
  "evidence": [
    {
      "source": "customer",
      "quote": "我该先核对哪些型号和尺寸？"
    },
    {
      "source": "customer",
      "quote": "我最近想给显卡改用一体式水冷"
    },
    {
      "source": "customer",
      "quote": "配我手头的冷排和显卡"
    }
  ],
  "issues": [
    "extraction.requirements[0] 将“给显卡改用一体式水冷”标为 strict 的 use_case；它表达的是改装背景或用途，不宜据此当作商品筛选硬条件。",
    "extraction.unknowns 为空，但具体显卡、冷排及安装架型号在当前请求中未知。由于顾客问的是核对方法而非要求立即验证具体组合，这些未知不构成必须先追问的门槛。"
  ]
}
